/// `Op08`.
///
/// Cut: Cycles, MemFetch, MemWrite, STATE.
pub(super) fn Op08(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Op08;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = st.pc().wrapping_add(0x1u128) & 0xffff;
    let s2: u128 = st.fetch(s1);
    let s3: u128 = st.pc().wrapping_add(0x2u128) & 0xffff;
    let s4: u128 = st.fetch(s3);
    let s5: u128 = (s4 << 8) | s2;
    let v6 = st.get(b, regs::SP);
    let v7 = b.extract(v6, 0, Width::new(8));
    let v8 = b.konst(Width::new(16), s5);
    st.write(b, v8, v7, 4, None);
    let s9: u128 = s5.wrapping_add(0x1u128) & 0xffff;
    let v10 = st.get(b, regs::SP);
    let v11 = b.extract(v10, 8, Width::new(8));
    let v12 = b.konst(Width::new(16), s9);
    st.write(b, v12, v11, 5, None);
    st.cycles(b, 5, None);
    Ok(())
}

/// `Op09`.
///
/// Cut: Cycles, STATE.
pub(super) fn Op09(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::Op09;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let v1 = st.get(b, regs::H);
    let v2 = st.get(b, regs::L);
    let v3 = b.concat(v1, v2);
    let v4 = st.get(b, regs::B);
    let v5 = st.get(b, regs::C);
    let v6 = b.concat(v4, v5);
    let v7 = b.zext(v3, Width::new(17));
    let v8 = b.zext(v6, Width::new(17));
    let v9 = b.bin(BinOp::Add, v7, v8);
    let v10 = b.konst(Width::new(16), 0xfff);
    let v11 = b.bin(BinOp::And, v3, v10);
    let v12 = b.konst(Width::new(16), 0xfff);
    let v13 = b.bin(BinOp::And, v6, v12);
    let v14 = b.bin(BinOp::Add, v11, v13);
    let v15 = b.extract(v9, 0, Width::new(16));
    let v16 = b.extract(v15, 8, Width::new(8));
    st.set(b, regs::H, v16, None);
    let v17 = b.extract(v15, 0, Width::new(8));
    st.set(b, regs::L, v17, None);
    let v18 = b.konst(Width::new(1), 0x0);
    st.set(b, regs::FN, v18, None);
    let v19 = b.extract(v14, 12, Width::new(1));
    st.set(b, regs::FH, v19, None);
    let v20 = b.extract(v9, 16, Width::new(1));
    st.set(b, regs::FC, v20, None);
    st.cycles(b, 2, None);
    Ok(())
}

