    let s5: u128 = (s4 << 8) | s2;
    let v6 = b.konst(Width::new(16), s5);
    let v7 = st.read(b, v6, 4, None);
    st.set(b, regs::A, v7, None);
    st.cycles(b, 4, None);
    Ok(())
