/// `OpFE`.
///
/// Cut: Cycles, MemFetch, STATE.
pub(super) fn OpFE(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::OpFE;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = st.pc().wrapping_add(0x1u128) & 0xffff;
    let s2: u128 = st.fetch(s1);
    let v3 = st.get(b, regs::A);
    let v4 = b.zext(v3, Width::new(9));
    let v5 = b.konst(Width::new(9), s2);
    let v6 = b.bin(BinOp::Sub, v4, v5);
    let v7 = b.konst(Width::new(9), 0x0);
    let v8 = b.bin(BinOp::Sub, v6, v7);
    let v9 = b.konst(Width::new(8), 0xf);
    let v10 = b.bin(BinOp::And, v3, v9);
    let s11: u128 = s2 & 0xfu128;
    let v12 = b.konst(Width::new(8), s11);
    let v13 = b.bin(BinOp::Sub, v10, v12);
    let v14 = b.konst(Width::new(8), 0x0);
    let v15 = b.bin(BinOp::Sub, v13, v14);
    let v16 = b.extract(v8, 0, Width::new(8));
    let v17 = b.extract(v15, 4, Width::new(1));
    let v18 = b.extract(v8, 8, Width::new(1));
    let v19 = b.konst(Width::new(8), 0x0);
    let v20 = b.cmp(CmpOp::Eq, v16, v19);
    let v22 = b.konst(Width::new(1), 0x1);
    let v23 = b.konst(Width::new(1), 0x0);
    let v24 = b.select(v20, v22, v23);
    st.set(b, regs::FZ, v24, None);
    let v25 = b.konst(Width::new(1), 0x1);
    st.set(b, regs::FN, v25, None);
    st.set(b, regs::FH, v17, None);
    st.set(b, regs::FC, v18, None);
    st.cycles(b, 2, None);
    Ok(())
}

/// `OpFF`.
///
/// Cut: BranchTo, Cycles, MemWrite, STATE.
pub(super) fn OpFF(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::OpFF;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let s1: u128 = st.pc().wrapping_add(0x1u128) & 0xffff;
    let v2 = st.get(b, regs::SP);
    let v3 = b.konst(Width::new(16), 0x1);
    let v4 = b.bin(BinOp::Sub, v2, v3);
    let v5 = st.get(b, regs::SP);
    let v6 = b.konst(Width::new(16), 0x2);
    let v7 = b.bin(BinOp::Sub, v5, v6);
    let s8: u128 = (s1 >> 8) & 0xff;
    let v9 = b.konst(Width::new(8), s8);
    st.write(b, v4, v9, 3, None);
    let s10: u128 = (s1 >> 0) & 0xff;
    let v11 = b.konst(Width::new(8), s10);
    st.write(b, v7, v11, 4, None);
    st.set(b, regs::SP, v7, None);
    st.branch(b, Target::Const((0x38u128) as u16), Kind::Call, None);
    st.cycles(b, 4, None);
    Ok(())
}

