/// `CbFE`.
///
/// Cut: Cycles, MemRead, MemWrite, STATE.
pub(super) fn CbFE(word: u32, b: &mut Builder, st: &mut St) -> Result<(), LiftError> {
    const ENC: Encoding = Encoding::CbFE;
    let w = u128::from(word);
    let pc = u128::from(b.pc());
    let v1 = st.get(b, regs::H);
    let v2 = st.get(b, regs::L);
    let v3 = b.concat(v1, v2);
    let v4 = st.read(b, v3, 3, None);
    let v5 = b.extract(v4, 0, Width::new(7));
    let v6 = b.konst(Width::new(1), 0x1);
    let v7 = b.concat(v6, v5);
    let v8 = st.get(b, regs::H);
    let v9 = st.get(b, regs::L);
    let v10 = b.concat(v8, v9);
    st.write(b, v10, v7, 4, None);
    st.cycles(b, 4, None);
    Ok(())
}

